func X2apInternalValidationReportAddIssue(r *ValidationReport, issue ValidationIssue) {
	if err := X2apInternalValidationReportReserveReport(r, issue.Location); err != nil {
		return
	}
	r.Issues = append(r.Issues, issue)
}
func X2apInternalValidationReportAddDeferred(r *ValidationReport, item s06.DeferredCondition) {
	if err := X2apInternalValidationReportReserveReport(r, item.Location); err != nil {
		return
	}
	r.Deferred = append(r.Deferred, item)
}
func X2apInternalValidationReportAddUnchecked(r *ValidationReport, location aper.Location) {
	if err := X2apInternalValidationReportReserveReport(r, location); err != nil {
		return
	}
	r.Unchecked = append(r.Unchecked, location)
}
func X2apInternalValidationReportReserveReport(r *ValidationReport, location aper.Location) error {
	if r.err != nil {
		return r.err
	}
	if r.budget == nil {
		return nil
	}
	bb := aper.NewBudgetBuffer(r.budget)
	if err := bb.ChargeLocatedReport(location, 1024); err != nil {
		r.err = err
		return err
	}
	return nil
}

type ValidationIssue struct {
	Code                s00.ValidationCode
	Severity            s00.ValidationSeverity
	Location            aper.Location
	Table               s00.TableID
	IEID                s00.ProtocolIEID
	HasIEID             bool
	PrivateID           *s00.PrivateIEID
	ExpectedCriticality *s00.Criticality
	ReceivedCriticality *s00.Criticality
	Rule                aper.SourceRule
	RelatedRules        []aper.SourceRule
}
type ValidationReport struct {
	budget    *aper.DecodeBudget
	err       error
	Issues    []ValidationIssue
	Deferred  []s06.DeferredCondition
	Unchecked []aper.Location
	Complete  bool
}

